/*
 * A032709  Numbers k such that k prefixed by '9' and followed by '1' is
 *          prime.
 * https://oeis.org/A032709
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   not stated
 * Range:     u8 none, u16 n <= 33, u32 n <= 33, u64 n <= 60, u128 n <= 60,
 *            big any n
 * Helpers:   digits, is_prime_big, pow10
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*  a(n) = the n-th integer k such that the decimal concatenation
 *  "9" + k + "1" is prime.  The sequence is generated by incremental
 *  search over k and is memoised in a static table.  The function
 *  works for any n ≥ 1 and for calls arriving in any order. */
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>

#include "../utils/digits.h"     /* int digits(idx_t x); */
#include "../utils/pow10.h"      /* seq_t pow10(idx_t e); */
#include "../utils/is_prime_big.h" /* bool is_prime_big(seq_t n); */

seq_t a(idx_t n)
{
    /* Static cache of previously found terms */
    static seq_t *cache       = NULL;
    static size_t cache_len   = 0;
    static size_t cache_cap   = 0;
    static idx_t next_k       = 1;      /* candidate to test next */

    /* Grow the cache until it contains at least n terms */
    while (cache_len < n) {
        /* Number of decimal digits of next_k */
        idx_t d = (idx_t)digits(next_k);

        /* Build the candidate number: 9 * 10^(d+1) + next_k * 10 + 1 */
        seq_t pow_part = pow10(d + 1);
        seq_t candidate = ((seq_t)9 * pow_part) + ((seq_t)next_k * 10) + 1;

        if (is_prime_big(candidate)) {
            /* Ensure enough capacity in the cache */
            if (cache_len == cache_cap) {
                size_t new_cap = (cache_cap < 64) ? 64 : cache_cap * 2;
                seq_t *new_cache = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
                if (!new_cache) {
                    /* Allocation failed – return 0 to signal error. */
                    return (seq_t)0;
                }
                cache = new_cache;
                cache_cap = new_cap;
            }
            cache[cache_len++] = next_k;
        }
        ++next_k;
    }
    return cache[n - 1];
}
